function largestOf(numbers) {
  let comparisons = 0;
  let largest = numbers[0];
  for (let i = 1; i < numbers.length; i++) {
    comparisons++;
    if (numbers[i] > largest) largest = numbers[i];
  }
  console.log('list size ' + numbers.length + ' -> largest ' + largest + ', ' + comparisons + ' comparisons');
  return largest;
}

largestOf([3, 9, 2, 7]);
largestOf([10, 20, 30, 40, 50]);

